public static int findNthLeapYear(int Y, int N) {
    int count = 0;
    int year = Y;
    while (true) {
        if (isLeapYear(year)) {
            count++;
            if (count == N) {
                return year;
            }
        }
        year++;
    }
}

private static boolean isLeapYear(int year) {
    if (year % 400 == 0) return true;
    if (year % 100 == 0) return false;
    return year % 4 == 0;
}
```

