public int minOperations(String[] logs) {
    int depth = 0;
    for (String log : logs) {
        if ("./".equals(log)) {
            // stay in current folder
            continue;
        }
        if ("../".equals(log)) {
            if (depth > 0) {
                depth--;                  // move up one folder
            }
        } else {
            // move into a subfolder (log ends with '/')
            depth++;
        }
    }
    return depth; // steps needed to return to the main folder
}

